export function touchProfile(id: string): TouchProfile {
  for (let i = 0; i < TOUCH_PROFILES.length; i++) { if (TOUCH_PROFILES[i].id === id) { return TOUCH_PROFILES[i]; } }
  return TOUCH_PROFILES[TOUCH_PROFILES.length - 1];
}
